ST.xhtml:p:
R_Trriger(CLK := g_bSlowcutEnableM);
IF R_Trriger.Q THEN(*记录X坐标*)
  dActCoordX := g_diXMachineCoordinate;
  g_bSlowcutEnableM := FALSE;
  nstate := 10;
END_IF;
IF dMaxOverride <= dMinOverride THEN
  dMaxOverride := dMinOverride +0.01;
END_IF;                      
CASE nState OF
  0:
    nstate := 0;
  10:
    dMoveDis := ABS(g_diXMachineCoordinate - dActCoordX);
    dSingalOverrid := (dMaxOverride - dMinOverride)/nSlowSetNum ;
    nSlowNum := Trunc(LREAL_TO_REAL(dMoveDis /(g_dSlowcutLengthM / nSlowSetNum)));
    IF nSlowNum > LREAL_TO_INT(nSlowSetNum) THEN
      nSlowNum := LREAL_TO_INT(nSlowSetNum);
    ELSIF nSlowNum < 0 THEN
      nSlowNum := 0;
    END_IF;
    g_doRealtimeOverrid:=dMaxOverride-dSingalOverrid*INT_TO_LREAL(nSlowNum);
    IF g_doRealtimeOverrid < dMinOverride THEN
      g_doRealtimeOverrid:= dMinOverride;
    END_IF;

    IF g_nLayerStart =500 THEN
      g_boSlowcutEnable := TRUE;
      g_bIsSetSlowCutEnableFlag := TRUE; 
    ELSE 
      g_boSlowcutEnable := FALSE;
    g_bIsSetSlowCutEnableFlag := FALSE; 
      nstate := 0;
    END_IF;
     IF g_bPlcPauseBuffer THEN
      nstate := 20;
    END_IF;
  20:
    IF g_bPlcStartBuffer THEN
      nState := 10;
    END_IF;
END_CASE;                   
IF g_bPlcResetBuffer THEN 
  g_boSlowcutEnable := FALSE;
  g_bSlowcutEnableM := FALSE;
  nstate := 0;
END_IF;
